    review_check( (string) ( $seed + 21 ) === $person['data']['external_ids']['tvmaze'] && 'draft' === Plugin::store()->resolved( $person['uuid'] )['mapping']['status'], 'Identity connection preserves the existing Person draft and publication status' );
