    $guide = Presentation::season_page( $show['uuid'], '7', '2' ); review_check( 1 === count( $guide['episodes'] ) && 51 === $guide['episodes'][0]['data']['episode_number'], 'Episode pagination includes the final row beyond the 50-Episode boundary' );
